import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import type { RPGNexusPanelProps, RPGGameState, RPGDynamicAction, RPGSceneData } from '../../types';
import { AgentName } from '../../types';
import { useGemini } from '../../context/GeminiIntegrationContext';
import { globalSoundEngine } from '../../lib/SoundEngine';
import { QuestCinemaEngine } from '../../lib/video/QuestCinemaEngine';
import LoreMapVisualizer from '../visuals/LoreMapVisualizer'; 
import { motion, AnimatePresence } from 'framer-motion';

interface GeminiTravelResponse {
  description: string;
  actions: Array<{ label: string; risk: number; type: 'explore' | 'talk' | 'fight' | 'ritual' | 'analyze' }>;
  oracleInsight: string;
  resonanceShift: number;
}

interface GeminiActionResponse {
  resultText: string;
  newActions: Array<{ label: string; risk: number; type: 'explore' | 'talk' | 'fight' | 'ritual' | 'analyze' }>;
  oracleInsight: string;
  impact: { entropyDelta: number; healthDelta: number; sanityDelta: number };
}

const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const firstBrace = cleanText.indexOf('{');
    const lastBrace = cleanText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        cleanText = cleanText.substring(firstBrace, lastBrace + 1);
    }
    return JSON.parse(cleanText) as T;
  } catch (e) {
    return null;
  }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Resonate with the Weave', type: 'ritual', risk: 0.2, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  height, addEchoMessage, activeProfile, onUpdateProfile, currentEntropy,
  savedState, onSaveState, onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();

  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "The Nexus Engine initializes. The weave of fate is yours to pull.", type: 'system', timestamp: Date.now() }],
    activeQuests: [], lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS, achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [], currentSceneDescription: "A threshold of pure possibility where the Tri-Sophian light meets the outer static.",
    currentSceneImageUrl: null, sceneHistory: [] 
  });

  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");
  const [isAnimatingScene, setIsAnimatingScene] = useState(false);
  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'scene' | 'map'>(savedState ? 'scene' : 'map');
  const [showHistoryLog, setShowHistoryLog] = useState(false);
  const [isAutoAudioEnabled, setIsAutoAudioEnabled] = useState(true);
  const [isAudioPlaying, setIsAudioPlaying] = useState(false);
  const [latestOracleInsight, setLatestOracleInsight] = useState<string | null>(null);

  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);

  const lastNarratedTextRef = useRef<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  // Auto-Save
  useEffect(() => {
    if (onSaveState) onSaveState(gameState);
  }, [gameState, onSaveState]);

  // Unified GM System Prompt
  const getGMSystemInstruction = useCallback(() => {
    return `You are the Nexus Engine, the Prime Game Master of the Tri-Sophian Codex. 
    STYLE: High-concept, mystical sci-fi/fantasy. Poetic, dense, and slightly detached.
    THEME: The world is built on "Axioms" and "Glyphs". Reality is a "Weft" or "Loom".
    SEEKER PROFILE: ${activeProfile?.name} is a ${activeProfile?.race} ${activeProfile?.class} with ${activeProfile?.energyAlignment} alignment.
    SYSTEM STATE: Current Entropy is ${currentEntropy.toFixed(3)}δ. 
    (High entropy means chaos, fractured logic, and danger. Low entropy means clarity, order, and stability).
    GOAL: React to user movements and actions with deep lore integration. Always provide choices that reflect the Seeker's unique class and race.`;
  }, [activeProfile, currentEntropy]);

  // Audio Narration Hook
  useEffect(() => {
    if (!isAutoAudioEnabled || gameState.narrativeHistory.length === 0 || isProcessingTurn) return;
    const latestNarration = [...gameState.narrativeHistory].reverse().find(n => n.type === 'narration');
    if (!latestNarration || latestNarration.text === lastNarratedTextRef.current) return;
    lastNarratedTextRef.current = latestNarration.text;
    handleNarrate(latestNarration.text);
  }, [gameState.narrativeHistory, isAutoAudioEnabled, isProcessingTurn]);

  const handleNarrate = async (text: string) => {
    if (!text) return;
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();
      setIsAudioPlaying(true);
      const audioData = await generateSpeech(text, 'Fenrir'); 
      if (audioData) {
        const buffer = await audioContextRef.current.decodeAudioData(audioData);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => setIsAudioPlaying(false);
        source.start(0);
      } else {
        setIsAudioPlaying(false);
      }
    } catch (e) {
      setIsAudioPlaying(false);
    }
  };

  const handleTravel = async (locationName: string, locationData: any) => {
    setViewMode('scene'); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); 
    setLatestOracleInsight(null);
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev, currentLocation: locationName,
      narrativeHistory: [...prev.narrativeHistory, { text: `Tuning your frequency to ${locationName}...`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const prompt = `TRAVEL: The Seeker has arrived at the "${locationName}". 
      Explain how their identity as a ${activeProfile?.race} ${activeProfile?.class} colors their perception of this place. 
      Incorporate the theme of ${locationData.genre || 'unmapped territory'}.
      Return JSON: { 
        "description": "Short, immersive arrival description (max 60 words)", 
        "actions": [ { "label": "Action name", "risk": 0.0-1.0, "type": "explore|ritual|talk|fight|analyze" } ], 
        "oracleInsight": "A cryptic piece of specific lore for this location",
        "resonanceShift": -0.01 to 0.01
      }`;

      const response = await invokeGemini(prompt, getGMSystemInstruction(), "application/json");
      const textData = cleanAndParseJSON<GeminiTravelResponse>(response);

      if (textData) {
        setLatestOracleInsight(textData.oracleInsight);
        if (textData.resonanceShift) onUpdateSystemMetrics(textData.resonanceShift, 0);

        const url = await generateImage(`Hyper-detailed cinematic masterwork of ${locationName}: ${textData.description}. Perspective: First-person. Mood: Mystical.`);

        setGameState(prev => ({
          ...prev, 
          currentSceneImageUrl: url || prev.currentSceneImageUrl,
          currentSceneDescription: textData.description,
          availableActions: textData.actions.map((a, i) => ({ ...a, id: `a-${i}-${Date.now()}`, isDynamic: true })),
          narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }],
          sceneHistory: url ? [...prev.sceneHistory, { imageUrl: url, location: locationName, description: textData.description, timestamp: Date.now() }] : prev.sceneHistory
        }));
      }
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn || !actionLabel.trim()) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); 
    setLatestOracleInsight(null);
    globalSoundEngine.playSFX('click');

    setGameState(prev => ({
        ...prev, narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    try {
        const historyContext = gameState.narrativeHistory.filter(n => n.type === 'narration').slice(-2).map(n => n.text).join(" ");
        const prompt = `ACTION: "${actionLabel}" at "${gameState.currentLocation}". 
        Context: ${historyContext}
        Describe the outcome, acknowledging the Seeker's ${activeProfile?.class} abilities.
        Return JSON: { 
          "resultText": "Consequences of the action (max 70 words)", 
          "newActions": [ { "label": "Next choice", "risk": 0.0-1.0, "type": "explore|ritual|talk|fight|analyze" } ], 
          "oracleInsight": "Deep lore reveal based on the outcome",
          "impact": { "entropyDelta": -0.05 to 0.05, "healthDelta": -20 to 10, "sanityDelta": -20 to 10 }
        }`;

        const response = await invokeGemini(prompt, getGMSystemInstruction(), "application/json");
        const outcome = cleanAndParseJSON<GeminiActionResponse>(response);

        if (outcome) {
            setLatestOracleInsight(outcome.oracleInsight);
            if (outcome.impact) {
                onUpdateSystemMetrics(outcome.impact.entropyDelta || 0, 0);
                // Update local vitals
                setGameState(prev => ({
                    ...prev,
                    vitals: {
                        integrity: Math.max(0, Math.min(100, prev.vitals.integrity + outcome.impact.healthDelta)),
                        sanity: Math.max(0, Math.min(100, prev.vitals.sanity + outcome.impact.sanityDelta))
                    }
                }));
            }

            const url = await generateImage(`Visualizing the impact: ${outcome.resultText}. Cinematic and atmospheric.`);

            setGameState(prev => ({
                ...prev,
                currentSceneImageUrl: url || prev.currentSceneImageUrl,
                availableActions: outcome.newActions.map((a, i) => ({ ...a, id: `na-${i}-${Date.now()}`, isDynamic: true })),
                narrativeHistory: [...prev.narrativeHistory, { text: outcome.resultText, type: 'narration', timestamp: Date.now() }],
                sceneHistory: url ? [...prev.sceneHistory, { imageUrl: url, location: prev.currentLocation, description: outcome.resultText, timestamp: Date.now() }] : prev.sceneHistory
            }));
        }
    } finally {
        setIsProcessingTurn(false);
    }
  };

  const getActionIcon = (type: string) => {
    switch (type) {
        case 'ritual': return 'ri-magic-line';
        case 'fight': return 'ri-sword-line';
        case 'talk': return 'ri-chat-3-line';
        case 'analyze': return 'ri-microscope-line';
        default: return 'ri-compass-3-line';
    }
  };

  const handleGenerateVideo = async () => {
      if (isAnimatingScene || !gameState.currentSceneImageUrl) return;
      setIsAnimatingScene(true);
      try {
          const videoUrl = await generateVideo(`Living landscape. ${gameState.currentSceneDescription}`, gameState.currentSceneImageUrl);
          if (videoUrl) setCurrentSceneVideoUrl(videoUrl);
      } finally {
          setIsAnimatingScene(false);
      }
  };

  const handleExportChronicleVideo = async () => {
      if (isExporting || gameState.sceneHistory.length === 0) return;
      setIsExporting(true);
      setExportProgress(0);
      try {
          const engine = new QuestCinemaEngine();
          const videoBlob = await engine.compileVideo(
              gameState.sceneHistory.slice(-20), 
              (p) => setExportProgress(Math.floor(p * 100)),
              (txt) => generateSpeech(txt, 'Fenrir')
          );
          const url = URL.createObjectURL(videoBlob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Starborn_Quest_${Date.now()}.webm`;
          a.click();
          URL.revokeObjectURL(url);
          addEchoMessage(AgentName.System, "Quest chronicle synthesized.", "text-emerald-400");
      } catch (e) {
          addEchoMessage(AgentName.System, "Synthesis failure.", "text-rose-400");
      } finally {
          setIsExporting(false);
      }
  };

  return (
    <div className="w-full h-full relative flex flex-col bg-slate-950 overflow-hidden rounded-xl border border-white/5 shadow-2xl" style={{ minHeight: height }}>
        {/* Background Layer */}
        <div className="absolute inset-0 z-0">
            {currentSceneVideoUrl ? (
                <video src={currentSceneVideoUrl} autoPlay loop muted className="w-full h-full object-cover opacity-60" />
            ) : gameState.currentSceneImageUrl ? (
                <img src={gameState.currentSceneImageUrl} className="w-full h-full object-cover opacity-60 animate-fade-in" />
            ) : (
                <div className="w-full h-full bg-slate-900" />
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-black via-black/20 to-black/80 pointer-events-none"></div>
        </div>

        {/* HUD UI */}
        <div className="relative z-10 p-6 flex flex-col h-full pointer-events-none">
            <div className="flex justify-between items-start pointer-events-auto">
                <motion.div initial={{ x: -20, opacity: 0 }} animate={{ x: 0, opacity: 1 }}>
                    <h3 className="text-white font-cinzel font-bold text-2xl drop-shadow-lg flex items-center gap-3">
                        <i className="ri-map-pin-2-fill text-indigo-400"></i> {gameState.currentLocation}
                    </h3>
                    <div className="flex gap-2 mt-2">
                        <div className="bg-black/60 px-2 py-1 rounded border border-white/10 text-[9px] font-mono text-emerald-400 uppercase">Integrity: {gameState.vitals.integrity}%</div>
                        <div className="bg-black/60 px-2 py-1 rounded border border-white/10 text-[9px] font-mono text-fuchsia-400 uppercase">Sanity: {gameState.vitals.sanity}%</div>
                    </div>
                </motion.div>

                <div className="flex gap-2">
                    <button onClick={() => setIsAutoAudioEnabled(!isAutoAudioEnabled)} className={`p-2 rounded-lg border transition-all pointer-events-auto flex items-center gap-2 ${isAutoAudioEnabled ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg shadow-indigo-500/30' : 'bg-black/60 border-white/10 text-slate-400'}`}>
                      <i className={`ri-volume-${isAudioPlaying ? 'up' : isAutoAudioEnabled ? 'down' : 'mute'}-line text-lg ${isAudioPlaying ? 'animate-pulse' : ''}`}></i>
                    </button>
                    <button onClick={() => setViewMode(prev => prev === 'scene' ? 'map' : 'scene')} className={`p-2 rounded-lg border transition-all pointer-events-auto ${viewMode === 'map' ? 'bg-indigo-600 border-indigo-400 text-white' : 'bg-black/60 border-white/10 text-slate-300'}`}>
                      <i className={`ri-${viewMode === 'scene' ? 'map-2' : 'landscape'}-line text-lg`}></i>
                    </button>
                    <button onClick={() => setShowHistoryLog(!showHistoryLog)} className={`p-2 rounded-lg border transition-all pointer-events-auto ${showHistoryLog ? 'bg-amber-600 border-amber-400 text-white' : 'bg-black/60 border-white/10 text-slate-300'}`}>
                      <i className="ri-history-line text-lg"></i>
                    </button>
                </div>
            </div>

            <div className="mt-auto pointer-events-auto max-w-4xl mx-auto w-full pb-8">
                <AnimatePresence mode="wait">
                {showHistoryLog ? (
                    <motion.div key="history" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="bg-black/95 p-8 rounded-2xl border border-slate-700 h-[500px] overflow-y-auto custom-scrollbar shadow-2xl">
                        <div className="flex justify-between items-center mb-6 border-b border-slate-800 pb-4 font-cinzel">
                            <h4 className="text-indigo-300 text-xl tracking-widest uppercase">The Seeker's Weft</h4>
                            <div className="flex gap-4">
                                <button onClick={handleExportChronicleVideo} className="bg-indigo-600 hover:bg-indigo-500 text-white text-xs px-4 py-2 rounded border border-indigo-400"><i className="ri-movie-fill mr-2"></i>SYNTHESIZE VIDEO</button>
                                <button onClick={() => setShowHistoryLog(false)}><i className="ri-close-line text-2xl text-slate-500"></i></button>
                            </div>
                        </div>
                        <div className="space-y-4">
                            {gameState.narrativeHistory.map((n, i) => (
                                <div key={i} className={`text-sm ${n.type === 'action' ? 'text-indigo-400 font-bold italic' : 'text-slate-300'}`}>
                                    <span className="opacity-30 text-[9px] font-mono mr-3 uppercase">{new Date(n.timestamp).toLocaleTimeString()}</span>
                                    {n.text}
                                </div>
                            ))}
                        </div>
                    </motion.div>
                ) : (
                    <motion.div key="active-story" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-6">
                        {latestOracleInsight && (
                            <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="max-w-md bg-indigo-950/90 backdrop-blur-xl p-3 rounded-lg border-l-4 border-indigo-500 shadow-2xl mb-4">
                                <div className="flex items-center gap-2 mb-1">
                                    <i className="ri-sparkling-fill text-indigo-400 text-xs"></i>
                                    <span className="text-[9px] font-bold text-indigo-300 uppercase tracking-widest">Nexus Insight</span>
                                </div>
                                <p className="text-[11px] text-indigo-100 italic font-cormorant">{latestOracleInsight}</p>
                            </motion.div>
                        )}

                        <div className="space-y-4">
                             <p className="text-xl md:text-2xl font-cormorant text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)] italic leading-relaxed font-medium bg-black/40 p-4 rounded-xl border border-white/5 backdrop-blur-sm">
                                {gameState.narrativeHistory.filter(n => n.type === 'narration').slice(-1)[0]?.text || "The Codex pulses, awaiting your vibration."}
                            </p>
                            {isProcessingTurn && (
                                <div className="flex items-center gap-3 px-4">
                                    <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-ping"></div>
                                    <div className="text-indigo-300 text-[10px] font-mono tracking-widest uppercase">Engine Recalibrating Reality...</div>
                                </div>
                            )}
                        </div>

                        <div className="space-y-4">
                            <div className="flex gap-2 items-center bg-black/80 p-2 rounded-xl border border-white/10 backdrop-blur-md focus-within:border-indigo-500/50 transition-all shadow-inner">
                                <input 
                                    type="text" value={customActionInput} onChange={e => setCustomActionInput(e.target.value)}
                                    placeholder="Input custom intent..."
                                    className="flex-grow bg-transparent p-3 text-lg text-white outline-none placeholder:text-slate-700 font-cormorant"
                                    onKeyDown={e => e.key === 'Enter' && handleAction(customActionInput)}
                                    disabled={isProcessingTurn}
                                />
                                <button onClick={() => handleAction(customActionInput)} className="bg-indigo-600 hover:bg-indigo-500 text-white w-14 h-14 rounded-lg flex items-center justify-center transition-all disabled:opacity-30" disabled={!customActionInput.trim() || isProcessingTurn}>
                                  <i className="ri-send-plane-fill text-2xl"></i>
                                </button>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                {gameState.availableActions.map(action => (
                                    <button key={action.id} onClick={() => handleAction(action.label, action.risk)} disabled={isProcessingTurn} className="p-4 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-left transition-all flex justify-between items-center backdrop-blur-xl group hover:border-indigo-500/50">
                                        <div className="flex items-center gap-3">
                                            <i className={`${getActionIcon(action.type || 'explore')} text-xl text-indigo-400 group-hover:text-indigo-300`}></i>
                                            <span className="font-cinzel text-xs text-slate-200 group-hover:text-white truncate pr-2 tracking-wide font-semibold">{action.label}</span>
                                        </div>
                                        <span className={`text-[9px] font-mono px-1.5 py-0.5 rounded bg-black/40 ${action.risk > 0.6 ? 'text-rose-400 border border-rose-900' : 'text-emerald-400 border border-emerald-900'}`}>
                                            {Math.round(action.risk * 100)}%
                                        </span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </motion.div>
                )}
                </AnimatePresence>
            </div>

            <div className="absolute right-6 bottom-8 flex flex-col gap-3 pointer-events-auto">
                 <button onClick={handleGenerateVideo} disabled={isAnimatingScene || !gameState.currentSceneImageUrl} className={`p-4 rounded-full bg-indigo-700 hover:bg-indigo-600 border border-indigo-400 shadow-2xl text-white transition-all hover:scale-110 disabled:opacity-50 ${isAnimatingScene ? 'animate-pulse' : ''}`} title="Animate Scene"><i className={`ri-magic-line text-xl ${isAnimatingScene ? 'animate-spin-slow' : ''}`}></i></button>
            </div>
        </div>

        {/* Synthesis Overlay */}
        <AnimatePresence>
            {isExporting && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1000] bg-black/95 flex flex-col items-center justify-center p-8 backdrop-blur-3xl">
                    <div className="text-center space-y-12 max-w-lg">
                        <div className="relative w-48 h-48 mx-auto">
                            <svg className="w-full h-full transform -rotate-90">
                                <circle cx="96" cy="96" r="80" stroke="#1e293b" strokeWidth="8" fill="transparent" />
                                <circle cx="96" cy="96" r="80" stroke="#6366f1" strokeWidth="8" fill="transparent" strokeDasharray={502} strokeDashoffset={502 - (502 * exportProgress / 100)} className="transition-all duration-300" strokeLinecap="round" />
                            </svg>
                            <div className="absolute inset-0 flex items-center justify-center font-mono text-4xl text-white font-bold">{exportProgress}%</div>
                        </div>
                        <h2 className="text-3xl font-cinzel text-white tracking-widest uppercase">Synthesizing Narrative</h2>
                        <p className="text-slate-400 font-cormorant italic">"Compiling fragments of your journey into an immutable temporal record."</p>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>

        <AnimatePresence>
            {viewMode === 'map' && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 z-40 bg-slate-950/98 backdrop-blur-3xl p-8 flex flex-col">
                    <div className="flex justify-between items-center mb-6">
                        <h4 className="text-3xl font-cinzel text-indigo-300 tracking-widest uppercase font-black">Codex Cartography</h4>
                        <button onClick={() => setViewMode('scene')} className="p-4 bg-white/5 hover:bg-white/10 text-white rounded-xl border border-white/10 transition-all active:scale-95"><i className="ri-close-line text-3xl"></i></button>
                    </div>
                    <div className="flex-grow rounded-2xl border border-indigo-500/30 overflow-hidden shadow-2xl">
                        <LoreMapVisualizer currentLocationId={gameState.currentLocation} onTravel={(n) => handleTravel(n.id, n)} width={1200} height={1000} />
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    </div>
  );
};

export default RPGNexusPanel;

import React, { createContext, useState, useCallback, useContext, ReactNode } from 'react';
import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai"; 
import type { GeminiContextType } from '../types';

const GeminiContext = createContext<GeminiContextType | undefined>(undefined);

// Helper to add WAV header to raw PCM data
const writeString = (view: DataView, offset: number, string: string) => {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
};

const addWavHeader = (pcmData: Uint8Array, sampleRate: number, numChannels: number, bitsPerSample: number): ArrayBuffer => {
  const headerLength = 44;
  const dataLength = pcmData.length;
  const buffer = new ArrayBuffer(headerLength + dataLength);
  const view = new DataView(buffer);

  writeString(view, 0, 'RIFF'); // ChunkID
  view.setUint32(4, 36 + dataLength, true); // ChunkSize
  writeString(view, 8, 'WAVE'); // Format
  writeString(view, 12, 'fmt '); // Subchunk1ID
  view.setUint32(16, 16, true); // Subchunk1Size (16 for PCM)
  view.setUint16(20, 1, true); // AudioFormat (1 for PCM)
  view.setUint16(22, numChannels, true); // NumChannels
  view.setUint32(24, sampleRate, true); // SampleRate
  view.setUint32(28, sampleRate * numChannels * (bitsPerSample / 8), true); // ByteRate
  view.setUint16(32, numChannels * (bitsPerSample / 8), true); // BlockAlign
  view.setUint16(34, bitsPerSample, true); // BitsPerSample
  writeString(view, 36, 'data'); // Subchunk2ID
  view.setUint32(40, dataLength, true); // Subchunk2Size

