  const handleTravel = async (locationName: string, locationData: any) => {
    setViewMode('scene'); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); 
    setLatestOracleInsight(null);
    globalSoundEngine.playSFX('pulse');

    setGameState(prev => ({
      ...prev, currentLocation: locationName,
      narrativeHistory: [...prev.narrativeHistory, { text: `Seeking coordinate: ${locationName}...`, type: 'action', timestamp: Date.now() }]
