export interface QuestFrame {
  image: HTMLImageElement;
  text: string;
  durationMs: number;
  audioBuffer?: AudioBuffer | null;
}

export class QuestCinemaEngine {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private mediaRecorder: MediaRecorder | null = null;
  private recordedChunks: Blob[] = [];
  private width: number = 1280;
  private height: number = 720;
  private fps: number = 30;

  constructor() {
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.width;
    this.canvas.height = this.height;
    this.ctx = this.canvas.getContext('2d', { alpha: false })!;
  }

  private async loadImage(src: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous'; 
      img.onload = () => resolve(img);
      img.onerror = (e) => reject(new Error(`Failed to load image: ${src}`));
      img.src = src;
    });
  }

  private wrapText(text: string, maxWidth: number): string[] {
    this.ctx.font = '32px "Cormorant", serif';
    const words = text.split(' ');
    const lines = [];
    let currentLine = words[0];
    for (let i = 1; i < words.length; i++) {
        const word = words[i];
        if (this.ctx.measureText(currentLine + " " + word).width < maxWidth) {
            currentLine += " " + word;
        } else {
            lines.push(currentLine);
            currentLine = word;
        }
    }
    lines.push(currentLine);
    return lines;
  }

  public async compileVideo(
    slides: { imageUrl: string; text: string }[],
    onProgress: (progress: number) => void,
    audioGenerator: (text: string) => Promise<ArrayBuffer | null>
  ): Promise<Blob> {
    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const destNode = audioCtx.createMediaStreamDestination();
    this.recordedChunks = [];

    // 1. Prepare Phase: Load assets and generate speech
    const frames: QuestFrame[] = [];

    // Add Title Frame
    const titleImg = new Image();
    titleImg.src = slides[0]?.imageUrl || ''; // Use first slide as base
    frames.push({ 
        image: titleImg, 
        text: "The Chronicle of a Seeker", 
        durationMs: 3000 
    });

    for (let i = 0; i < slides.length; i++) {
      onProgress((i / slides.length) * 0.5); 
      try {
        const img = await this.loadImage(slides[i].imageUrl);
        let audioBuffer: AudioBuffer | null = null;
        let durationMs = 6000; 

        const audioData = await audioGenerator(slides[i].text);
        if (audioData) {
          audioBuffer = await audioCtx.decodeAudioData(audioData);
          durationMs = Math.max(durationMs, (audioBuffer.duration * 1000) + 1500);
        }

        frames.push({ image: img, text: slides[i].text, durationMs, audioBuffer });
      } catch (e) {
        console.warn("Skipping corrupt slide during synthesis:", e);
      }
    }

    if (frames.length === 0) throw new Error("No valid chronicle entries to export.");

    // 2. Setup Recording Streams
    const canvasStream = this.canvas.captureStream(this.fps);
    const combinedStream = new MediaStream([
      ...canvasStream.getVideoTracks(),
      ...destNode.stream.getAudioTracks()
    ]);

    this.mediaRecorder = new MediaRecorder(combinedStream, {
      mimeType: 'video/webm;codecs=vp9,opus',
      videoBitsPerSecond: 8000000
    });

    return new Promise((resolve, reject) => {
      this.mediaRecorder!.ondataavailable = (e) => { if (e.data.size > 0) this.recordedChunks.push(e.data); };
      this.mediaRecorder!.onstop = () => {
        audioCtx.close();
        resolve(new Blob(this.recordedChunks, { type: 'video/webm' }));
      };
      this.mediaRecorder!.onerror = (e) => reject(e);
      this.mediaRecorder!.start();

      let currentIdx = 0;
      let startTime = performance.now();
      let audioTriggered = false;

      const animate = (now: number) => {
        if (currentIdx >= frames.length) {
          this.mediaRecorder?.stop();
          return;
        }

        const frame = frames[currentIdx];
        const elapsed = now - startTime;
        const frameT = Math.min(1, elapsed / frame.durationMs);

        onProgress(0.5 + (currentIdx + frameT) / frames.length * 0.5);

        if (!audioTriggered && frame.audioBuffer) {
          const source = audioCtx.createBufferSource();
          source.buffer = frame.audioBuffer;
          source.connect(destNode);
          source.start();
          audioTriggered = true;
        }

        // Draw Frame
        this.ctx.fillStyle = '#000';
        this.ctx.fillRect(0, 0, this.width, this.height);

        // Ken Burns Effect
        const zoom = 1 + (frameT * 0.15);
        const dw = this.width * zoom;
        const dh = this.height * zoom;
        this.ctx.drawImage(frame.image, (this.width - dw) / 2, (this.height - dh) / 2, dw, dh);

        // Narrative Overlay
        this.ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        this.ctx.fillRect(0, this.height - 200, this.width, 200);

        // Visual Flourish: Progress Line
        this.ctx.fillStyle = 'rgba(129, 140, 248, 0.5)';
        this.ctx.fillRect(0, this.height - 202, this.width * frameT, 2);

        // Frame text
        this.ctx.font = 'bold 28px "Cinzel", serif';
        this.ctx.fillStyle = '#818cf8';
        this.ctx.textAlign = 'center';

        if (currentIdx === 0) {
            this.ctx.font = 'bold 64px "Cinzel", serif';
            this.ctx.fillText(frame.text, this.width / 2, this.height / 2);
        } else {
            const lines = this.wrapText(frame.text, this.width - 240);
            this.ctx.font = 'italic 32px "Cormorant", serif';
            this.ctx.fillStyle = '#f8fafc';
            lines.slice(0, 4).forEach((l, i) => {
              this.ctx.fillText(l, this.width / 2, this.height - 150 + (i * 42));
            });
        }

        if (elapsed >= frame.durationMs) {
          currentIdx++;
          startTime = now;
          audioTriggered = false;
        }

        requestAnimationFrame(animate);
      };

      requestAnimationFrame(animate);
    });
  }
}

