                        <div className="space-y-4" role="main">
                             <p className="text-xl md:text-2xl font-cormorant text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)] italic leading-relaxed font-medium bg-black/40 p-4 rounded-xl border border-white/5 backdrop-blur-sm">
                                {gameState.narrativeHistory.filter(n => n.type === 'narration').slice(-1)[0]?.text || "The Codex pulses, awaiting your vibration."}
