                                <button onClick={() => handleAction(customActionInput)} className="bg-indigo-600 hover:bg-indigo-500 text-white w-14 h-14 rounded-lg flex items-center justify-center transition-all disabled:opacity-30" disabled={!customActionInput.trim() || isProcessingTurn} aria-label="Submit custom action">
                                  <i className="ri-send-plane-fill text-2xl"></i>
                                </button>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                {gameState.availableActions.map(action => (
                                    <button 
                                      key={action.id} 
                                      onClick={() => handleAction(action.label, action.risk)} 
                                      disabled={isProcessingTurn} 
                                      className="p-4 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-left transition-all flex justify-between items-center backdrop-blur-xl group hover:border-indigo-500/50"
                                      aria-label={`Action: ${action.label}. Risk: ${Math.round(action.risk * 100)} percent`}
                                    >
                                        <div className="flex items-center gap-3">
                                            <i className={`${getActionIcon(action.type || 'explore')} text-xl text-indigo-400 group-hover:text-indigo-300`} aria-hidden="true"></i>
                                            <span className="font-cinzel text-xs text-slate-200 group-hover:text-white truncate pr-2 tracking-wide font-semibold">{action.label}</span>
                                        </div>
                                        <span className={`text-[9px] font-mono px-1.5 py-0.5 rounded bg-black/40 ${action.risk > 0.6 ? 'text-rose-400 border border-rose-900' : 'text-emerald-400 border border-emerald-900'}`} aria-hidden="true">
                                            {Math.round(action.risk * 100)}%
                                        </span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </motion.div>
                )}
                </AnimatePresence>
            </div>
        </div>

        <AnimatePresence>
            {viewMode === 'map' && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 z-40 bg-slate-950/98 backdrop-blur-3xl p-8 flex flex-col">
                    <div className="flex justify-between items-center mb-6">
                        <h4 className="text-3xl font-cinzel text-indigo-300 tracking-widest uppercase font-black">Codex Cartography</h4>
                        <button onClick={() => setViewMode('scene')} className="p-4 bg-white/5 hover:bg-white/10 text-white rounded-xl border border-white/10 transition-all active:scale-95" aria-label="Back to Scene"><i className="ri-close-line text-3xl"></i></button>
                    </div>
                    <div className="flex-grow rounded-2xl border border-indigo-500/30 overflow-hidden shadow-2xl">
                        <LoreMapVisualizer currentLocationId={gameState.currentLocation} onTravel={(n) => handleTravel(n.id, n)} width={1200} height={1000} />
                    </div>
                </motion.div>
            )}
        </AnimatePresence>
    </div>
  );
};

