// --- Raw Audio Decoding Utilities ---
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPcm(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const cleanAndParseJSON = <T,>(text: string | null): T | null => {
  if (!text) return null;
  try {
    let cleanText = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const firstBrace = cleanText.indexOf('{');
    const lastBrace = cleanText.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1) {
        cleanText = cleanText.substring(firstBrace, lastBrace + 1);
    }
    return JSON.parse(cleanText) as T;
  } catch (e) {
    return null;
  }
};

const DEFAULT_ACTIONS: RPGDynamicAction[] = [
    { id: 'def_explore', label: 'Survey the Area', type: 'explore', risk: 0.1, isDynamic: false },
    { id: 'def_scan', label: 'Resonate with the Weave', type: 'ritual', risk: 0.2, isDynamic: false }
];

const RPGNexusPanel: React.FC<RPGNexusPanelProps> = ({
  height, addEchoMessage, activeProfile, onUpdateProfile, currentEntropy,
  savedState, onSaveState, onUpdateSystemMetrics
}) => {
  const { invokeGemini, generateImage, generateVideo, generateSpeech, isGenerating } = useGemini();

  const [gameState, setGameState] = useState<RPGGameState>(savedState || {
    currentLocation: 'The Void Edge',
    narrativeHistory: [{ text: "The Nexus Engine initializes. The weave of fate is yours to pull.", type: 'system', timestamp: Date.now() }],
    activeQuests: [], lastActionTimestamp: Date.now(),
    vitals: { integrity: 100, sanity: 100 },
    availableActions: DEFAULT_ACTIONS, achievements: [],
    combatState: { isActive: false, enemyName: '', enemyHp: 0, enemyMaxHp: 0, turn: 0, logs: [] },
    knownLocations: [], currentSceneDescription: "A threshold of pure possibility where the Tri-Sophian light meets the outer static.",
    currentSceneImageUrl: null, sceneHistory: [] 
  });

  const [currentSceneVideoUrl, setCurrentSceneVideoUrl] = useState<string | null>(null);
  const [isProcessingTurn, setIsProcessingTurn] = useState(false);
  const [customActionInput, setCustomActionInput] = useState("");
  const [viewMode, setViewMode] = useState<'scene' | 'map'>(savedState ? 'scene' : 'map');
  const [showHistoryLog, setShowHistoryLog] = useState(false);
  const [isAutoAudioEnabled, setIsAutoAudioEnabled] = useState(true);
  const [isAudioPlaying, setIsAudioPlaying] = useState(false);
  const [latestOracleInsight, setLatestOracleInsight] = useState<string | null>(null);

  const [isExporting, setIsExporting] = useState(false);
  const [exportProgress, setExportProgress] = useState(0);

  const lastNarratedTextRef = useRef<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  const getGMSystemInstruction = useCallback(() => {
    return `You are the Nexus Engine, the Prime Game Master of the Tri-Sophian Codex. 
    STYLE: High-concept, mystical sci-fi. 
    SEEKER: ${activeProfile?.name} (${activeProfile?.class}).
    ENTROPY: ${currentEntropy.toFixed(3)}δ. 
    REQUIREMENT: Provide "newActions" that are EXPLICITLY derived from the "resultText". Use specific nouns from the scene. If no actions are logical, provide 'Deepen the connection' as a fallback.`;
  }, [activeProfile, currentEntropy]);

  const handleNarrate = async (text: string) => {
    if (!text || !isAutoAudioEnabled) return;
    try {
      // CRITICAL: Force stop previous source to prevent overlapping
      if (currentAudioSourceRef.current) {
        try {
          currentAudioSourceRef.current.stop();
        } catch (e) {}
        currentAudioSourceRef.current = null;
      }

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      if (audioContextRef.current.state === 'suspended') await audioContextRef.current.resume();

      setIsAudioPlaying(true);
      const base64Audio = await generateSpeech(text, 'Fenrir'); 
      if (base64Audio) {
        const rawBytes = decodeBase64(base64Audio);
        const buffer = await decodeRawPcm(rawBytes, audioContextRef.current, 24000, 1);

        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => {
          if (currentAudioSourceRef.current === source) {
            setIsAudioPlaying(false);
          }
        };
        currentAudioSourceRef.current = source;
        source.start(0);
      } else {
        setIsAudioPlaying(false);
      }
    } catch (e) {
      console.error("Aural Weave Failure:", e);
      setIsAudioPlaying(false);
    }
  };

  const handleExportVideo = async () => {
    if (gameState.sceneHistory.length < 1 || isExporting) {
      addEchoMessage('System', 'Insufficient chronicle history.', 'text-rose-400');
      return;
    }
    setIsExporting(true);
    setExportProgress(0);
    try {
      const cinema = new QuestCinemaEngine();
      const audioGen = async (text: string) => {
          const b64 = await generateSpeech(text);
          return b64 ? decodeBase64(b64).buffer : null;
      };
      const videoBlob = await cinema.compileVideo(
        gameState.sceneHistory.map(s => ({ imageUrl: s.imageUrl, text: s.description })),
        (p) => setExportProgress(Math.floor(p * 100)),
        audioGen
      );
      const url = URL.createObjectURL(videoBlob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `Chronicle_${activeProfile?.name || 'Seeker'}.webm`;
      a.click();
      URL.revokeObjectURL(url);
    } finally {
      setIsExporting(false);
    }
  };

  useEffect(() => {
    const latest = [...gameState.narrativeHistory].reverse().find(n => n.type === 'narration');
    if (latest && latest.text !== lastNarratedTextRef.current && !isProcessingTurn) {
      lastNarratedTextRef.current = latest.text;
      handleNarrate(latest.text);
    }
  }, [gameState.narrativeHistory, isProcessingTurn]);

  const handleTravel = async (locationName: string, locationData: any) => {
    setViewMode('scene'); 
    setIsProcessingTurn(true);
    setCurrentSceneVideoUrl(null); 
    setLatestOracleInsight(null);

    setGameState(prev => ({
      ...prev, currentLocation: locationName,
      narrativeHistory: [...prev.narrativeHistory, { text: `Seeking coordinate: ${locationName}...`, type: 'action', timestamp: Date.now() }]
    }));

    try {
      const prompt = `TRAVEL: Seeker reaches "${locationName}". Return JSON: { "description": "...", "actions": [...], "oracleInsight": "...", "resonanceShift": 0.0 }`;
      const response = await invokeGemini(prompt, getGMSystemInstruction(), "application/json");
      const textData = cleanAndParseJSON<GeminiTravelResponse>(response);

      if (textData) {
        setLatestOracleInsight(textData.oracleInsight);
        if (textData.resonanceShift) onUpdateSystemMetrics(textData.resonanceShift, 0);
        const url = await generateImage(`Cinematic first-person shot of ${locationName}: ${textData.description}`);

        setGameState(prev => {
          const rawActions = textData.actions || [];
          const validatedActions = rawActions.length > 0 ? rawActions : DEFAULT_ACTIONS;
          const newState = {
            ...prev, 
            currentSceneImageUrl: url || prev.currentSceneImageUrl,
            currentSceneDescription: textData.description,
            availableActions: validatedActions.map((a, i) => ({ ...a, id: `a-${i}-${Date.now()}`, isDynamic: true })),
            narrativeHistory: [...prev.narrativeHistory, { text: textData.description, type: 'narration', timestamp: Date.now() }],
            sceneHistory: url ? [...prev.sceneHistory, { imageUrl: url, location: locationName, description: textData.description, timestamp: Date.now() }] : prev.sceneHistory
          };
          if (onSaveState) onSaveState(newState);
          return newState;
        });
      }
    } finally {
      setIsProcessingTurn(false);
    }
  };

  const handleAction = async (actionLabel: string, risk: number = 0.5) => {
    if (isProcessingTurn || !actionLabel.trim()) return;
    setIsProcessingTurn(true);
    setCustomActionInput(""); 
    setLatestOracleInsight(null);
    setCurrentSceneVideoUrl(null);

    setGameState(prev => ({
        ...prev, narrativeHistory: [...prev.narrativeHistory, { text: `> ${actionLabel}`, type: 'action', timestamp: Date.now() }]
    }));

    try {
        const lastDesc = [...gameState.narrativeHistory].reverse().find(n => n.type === 'narration')?.text;
