        const response = await invokeGemini(prompt, getGMSystemInstruction(), "application/json");
        const outcome = cleanAndParseJSON<GeminiActionResponse>(response);

        if (outcome) {
            setLatestOracleInsight(outcome.oracleInsight);
            if (outcome.impact) onUpdateSystemMetrics(outcome.impact.entropyDelta || 0, 0);
            const url = await generateImage(`Visual: ${outcome.resultText}`);

            setGameState(prev => {
                const rawActions = outcome.newActions || [];
                const validatedActions = rawActions.length > 0 ? rawActions : DEFAULT_ACTIONS;
                const newState = {
                  ...prev,
                  currentSceneImageUrl: url || prev.currentSceneImageUrl,
                  vitals: outcome.impact ? {
                      integrity: Math.max(0, Math.min(100, prev.vitals.integrity + outcome.impact.healthDelta)),
                      sanity: Math.max(0, Math.min(100, prev.vitals.sanity + outcome.impact.sanityDelta))
