import React, { useEffect, useRef, useState } from 'react';
import type { EchoMessage } from '../types';
import { useGemini } from '../context/GeminiIntegrationContext';

// --- Raw Audio Decoding Utilities ---
function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeRawPcm(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

interface EchoScribePanelProps {
  echoes: EchoMessage[];
}

export const EchoScribePanel: React.FC<EchoScribePanelProps> = ({ echoes }) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const { generateSpeech } = useGemini();
  const [isNarratorEnabled, setIsNarratorEnabled] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const lastReadIdRef = useRef<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const currentAudioSourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollTop = 0; 
    }
  }, [echoes]);

  const handleNarrate = async (text: string) => {
    if (!text) return;

    try {
      // Clear previous audio to prevent overlapping
      if (currentAudioSourceRef.current) {
        try {
          currentAudioSourceRef.current.stop();
        } catch (e) {}
        currentAudioSourceRef.current = null;
      }

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }

      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      setIsPlaying(true);
      const base64Audio = await generateSpeech(text, 'Kore'); 

      if (base64Audio) {
        const rawBytes = decodeBase64(base64Audio);
        const buffer = await decodeRawPcm(rawBytes, audioContextRef.current, 24000, 1);
        const source = audioContextRef.current.createBufferSource();
        source.buffer = buffer;
        source.connect(audioContextRef.current.destination);
        source.onended = () => {
          if (currentAudioSourceRef.current === source) {
            setIsPlaying(false);
          }
        };
        currentAudioSourceRef.current = source;
        source.start(0);
      } else {
        setIsPlaying(false);
      }
    } catch (e) {
      console.error("Log Narration failed", e);
      setIsPlaying(false);
    }
  };

  useEffect(() => {
    if (!isNarratorEnabled || echoes.length === 0) return;

    const latestEcho = echoes[0];
    if (latestEcho.id === lastReadIdRef.current) return;

    lastReadIdRef.current = latestEcho.id;
    handleNarrate(latestEcho.text);

  }, [echoes, isNarratorEnabled]);

  const toggleNarrator = () => {
    setIsNarratorEnabled(!isNarratorEnabled);
    if (!isNarratorEnabled && currentAudioSourceRef.current) {
        try {
          currentAudioSourceRef.current.stop();
        } catch (e) {}
    }
  };

  return (
    <div className="bg-slate-900/80 backdrop-blur-sm border border-slate-700 rounded-lg p-6 relative overflow-hidden">
      <div className="flex justify-between items-center mb-6">
        <div className="flex items-center gap-2">
            <div className="text-lg font-semibold text-slate-200 font-cinzel">Echo Log</div>
            {isPlaying && (
                <div className="flex items-center gap-1">
                    <span className="w-1 h-3 bg-indigo-500 animate-pulse"></span>
                    <span className="w-1 h-4 bg-indigo-400 animate-pulse delay-75"></span>
                    <span className="w-1 h-2 bg-indigo-600 animate-pulse delay-150"></span>
                </div>
            )}
        </div>
        <div className="flex space-x-2">
          <button 
            onClick={toggleNarrator}
            className={`rounded-button px-3 py-1.5 text-sm transition flex items-center border ${
                isNarratorEnabled 
                ? 'bg-indigo-600 border-indigo-400 text-white' 
                : 'bg-slate-800 border-slate-700 text-slate-400 hover:text-slate-200'
            }`}
            title={isNarratorEnabled ? "Disable Narrator" : "Enable Narrator"}
            aria-label="Toggle auto-narration"
          >
            <i className={`ri-volume-${isNarratorEnabled ? 'up' : 'mute'}-line mr-1`}></i>
            <span className="hidden sm:inline">{isNarratorEnabled ? 'On' : 'Off'}</span>
          </button>
        </div>
      </div>

      <div ref={scrollContainerRef} className="h-64 overflow-y-auto space-y-4 p-2 bg-slate-800/50 rounded-md shadow-inner custom-scrollbar-thin">
        {echoes.length === 0 ? (
            <div className="h-full flex items-center justify-center text-slate-600 italic font-cormorant">
                Awaiting resonance...
            </div>
        ) : (
            echoes.map((echo) => (
                <div key={echo.id} className="echo-message font-cormorant group animate-fade-in-up">
                  <div className="flex justify-between items-center mb-0.5">
                    <span className={`${echo.colorClass} uppercase text-[10px] tracking-widest font-cinzel font-bold`}>
                        {echo.source}
                    </span>
                    <button 
                        onClick={() => handleNarrate(echo.text)}
                        className="opacity-0 group-hover:opacity-100 text-slate-500 hover:text-indigo-400 transition-opacity"
                        aria-label="Speak message"
                    >
                        <i className="ri-volume-up-line"></i>
                    </button>
                  </div>
                  <div className="text-slate-200 whitespace-pre-line italic ml-2 border-l border-slate-700/50 pl-3 leading-relaxed">
                    {echo.text}
                  </div>
                </div>
            ))
        )}
      </div>
    </div>
  );
};

