                                <div className="flex items-center gap-2 mb-1">
                                    <i className="ri-sparkling-fill text-indigo-400 text-xs"></i>
                                    <span className="text-[9px] font-bold text-indigo-300 uppercase tracking-widest">Nexus Insight</span>
                                </div>
                                <p className="text-[11px] text-indigo-100 italic font-cormorant">{latestOracleInsight}</p>
                            </motion.div>
                        )}

                        <div className="space-y-4">
                             <p className="text-xl md:text-2xl font-cormorant text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)] italic leading-relaxed font-medium bg-black/40 p-4 rounded-xl border border-white/5 backdrop-blur-sm">
                                {gameState.narrativeHistory.filter(n => n.type === 'narration').slice(-1)[0]?.text || "The Codex pulses..."}
                            </p>
                        </div>

                        <div className="space-y-4">
                            <div className="flex gap-2 items-center bg-black/80 p-2 rounded-xl border border-white/10 backdrop-blur-md focus-within:border-indigo-500/50 transition-all shadow-inner">
                                <input 
                                    type="text" value={customActionInput} onChange={e => setCustomActionInput(e.target.value)}
                                    placeholder="Input custom intent..."
                                    className="flex-grow bg-transparent p-3 text-lg text-white outline-none placeholder:text-slate-700 font-cormorant"
                                    onKeyDown={e => e.key === 'Enter' && handleAction(customActionInput)}
