                                <button onClick={() => handleAction(customActionInput)} className="bg-indigo-600 hover:bg-indigo-500 text-white w-14 h-14 rounded-lg flex items-center justify-center transition-all disabled:opacity-30" disabled={!customActionInput.trim() || isProcessingTurn}>
                                  <i className="ri-send-plane-fill text-2xl"></i>
                                </button>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
                                {(gameState.availableActions || []).map(action => (
                                    <button 
                                      key={action.id} 
                                      onClick={() => handleAction(action.label, action.risk)} 
                                      disabled={isProcessingTurn} 
                                      className="p-4 bg-white/5 hover:bg-white/10 border border-white/10 rounded-xl text-left transition-all flex justify-between items-center backdrop-blur-xl group hover:border-indigo-500/50"
                                      aria-label={`Action: ${action.label}`}
