                                        <div className="flex items-center gap-3">
                                            <i className={`${getActionIcon(action.type || 'explore')} text-xl text-indigo-400 group-hover:text-indigo-300`}></i>
                                            <span className="font-cinzel text-xs text-slate-200 group-hover:text-white truncate pr-2 tracking-wide font-semibold">{action.label}</span>
                                        </div>
                                        <span className={`text-[9px] font-mono px-1.5 py-0.5 rounded bg-black/40 ${action.risk > 0.6 ? 'text-rose-400 border border-rose-900' : 'text-emerald-400 border border-emerald-900'}`}>
                                            {Math.round(action.risk * 100)}%
                                        </span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    </motion.div>
                )}
                </AnimatePresence>
            </div>
        </div>

        <AnimatePresence>
            {viewMode === 'map' && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="absolute inset-0 z-40 bg-slate-950/98 backdrop-blur-3xl p-8 flex flex-col">
